#!/bin/bash
# queue_one.sh STORY NUM "TITLE": the final of one story (the body of stories7/queue11.sh with the number and title as arguments): 3D layer at
# 1080x1920 30 fps with three browsers -> HyperFrames project (captions, cards, -16 LUFS mix) -> HyperFrames render. Logs in $PIPE/s7/STORY/,
# a status line in $PIPE/s7/queue.log. Do not edit this file while a run of it is going (bash reads a script as it runs).
source "$(dirname "${BASH_SOURCE[0]}")/env.sh"
S=$1; NUM=$2; TITLE=$3; SC=$PIPE/s7
cd $ROOT || exit 1
mkdir -p $SC/$S out
cp scripts-fr/story_$S.json scripts-fr/story_${S}_render.json
node render/render3.mjs scripts-fr/story_${S}_render.json --timed --w 1080 --h 1920 --workers 3 --out out/story_${S}_3d.mp4 > $SC/$S/render2.log 2>&1 || { echo "$S 3D FAILED" >> $SC/queue.log; exit 1; }
bash $PIPELINE_DIR/hf_only.sh $S $NUM "$TITLE"
